			var payload = new JObject {
				["event"] = ev,
				["args"]  = new JArray(args)
			};

			var str    = payload.ToString(Formatting.None);
			var buffer = Encoding.UTF8.GetBytes(str);



		}
	}
}

using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server _server;
		private TcpClient _client;
		private NetworkStream _stream;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
			_stream = _client.GetStream();
		}

		public EndPoint GetEndPoint() => _client?.Client?.RemoteEndPoint;

		public bool IsConnected() => _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_stream?.Close();
				_client?.Close();
				_client = null;
				_stream = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer() => _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			try {
				var payload = new JObject {
					["event"] = ev,
					["args"] = new JArray(args)
				};

				var str = payload.ToString(Formatting.None);
				var buffer = Encoding.UTF8.GetBytes(str + "\n");

				await _stream.WriteAsync(buffer, 0, buffer.Length);
			} catch (Exception ex) {
				Logger.LogError($"Error sending data to client {GetEndPoint()}: {ex.Message}");
			}
		}
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		public void OnInitializeMain(MainModCoreAPI api) { }

		public void OnDisposeMain() { }
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;
using UnityEngine;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		private WebSocketServerManager _serverManager;

		public void OnInitializeMain(MainModCoreAPI api) {
			// Create WebSocket server manager
			var serverObject = new GameObject("WebSocketServerManager");
			_serverManager = serverObject.AddComponent<WebSocketServerManager>();
			Object.DontDestroyOnLoad(serverObject);

			// Subscribe to events
			_serverManager.OnClientConnected += OnClientConnected;
			_serverManager.OnClientDisconnected += OnClientDisconnected;
			_serverManager.OnMessageReceived += OnMessageReceived;

			Debug.Log("WebSocket module initialized");
		}

		private void OnClientConnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client connected: {client.Id} from {client.RemoteEndpoint}");
		}

		private void OnClientDisconnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client disconnected: {client.Id}");
		}

		private void OnMessageReceived(WebSocketClient client, string message) {
			Debug.Log($"[WebSocket] Message from {client.Id}: {message}");
		}

		public void OnDisposeMain() {
			if (_serverManager != null) {
				_serverManager.OnClientConnected -= OnClientConnected;
				_serverManager.OnClientDisconnected -= OnClientDisconnected;
				_serverManager.OnMessageReceived -= OnMessageReceived;

				_serverManager.StopServer();
				Object.Destroy(_serverManager.gameObject);
			}

			Debug.Log("WebSocket module disposed");
		}
	}
}

using System;

namespace api.nox.websocket {
	/// <summary>
	/// Message types for WebSocket communication
	/// </summary>
	public enum MessageType {
		Text,
		Binary,
		Ping,
		Pong,
		Close
	}

	/// <summary>
	/// WebSocket message data
	/// </summary>
	public class WebSocketMessage {
		public MessageType Type { get; set; }
		public string TextData { get; set; }
		public byte[] BinaryData { get; set; }
		public WebSocketClient Sender { get; set; }
		public DateTime Timestamp { get; set; }

		public WebSocketMessage() {
			Timestamp = DateTime.UtcNow;
		}

		public static WebSocketMessage CreateTextMessage(string text, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Text,
				TextData = text,
				Sender = sender
			};
		}

		public static WebSocketMessage CreateBinaryMessage(byte[] data, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Binary,
				BinaryData = data,
				Sender = sender
			};
		}
	}
}

# Implémentation YantraBacking - Documentation Technique

##  Vue d'ensemble

Le système **YantraBacking** a été entièrement implémenté en utilisant l'API **YantraJS.Core v1.2.293**. Cette implémentation permet d'exécuter du code JavaScript dans Unity via le moteur YantraJS.

##  Architecture

### Composants Principaux

#### 1. JSContext
- **Responsabilité** : Contexte d'exécution JavaScript
- **Création** : Instancié dans la méthode `Prepare()`
- **Destruction** : Disposed dans la méthode `OnDestroy()`
- **Cycle de vie** : Géré automatiquement par Unity

#### 2. JSValue (ExecutionContext)
- **Responsabilité** : Résultat de l'exécution du script
- **Type** : Objet JavaScript contenant toutes les exportations
- **Accès** : Via l'indexeur `ExecutionContext[propertyName]`

#### 3. ClrProxy
- **Responsabilité** : Conversion des objets C# vers JavaScript
- **Usage** : `ClrProxy.From(Context, csharpObject)`
- **Types supportés** : Tous les types .NET et Unity

### Enregistrement des Types Unity

```csharp
Context.RegisterType(typeof(GameObject));
Context.RegisterType(typeof(Vector3));
Context.RegisterType(typeof(Vector2));
Context.RegisterType(typeof(Quaternion));
Context.RegisterType(typeof(Transform));
```

Ces types sont directement accessibles en JavaScript sans import.

##  Système d'Exports

### Principe
Les exports permettent d'exposer des variables Unity au contexte JavaScript.

### Implémentation
```csharp
var exportsDict = script.GetExports();
var exportsObj = JSObject.NewObject(Context);
foreach (var kvp in exportsDict) {
    if (kvp.Value != null) {
        exportsObj[kvp.Key] = ClrProxy.From(Context, kvp.Value);
    }
}
Context["exports"] = exportsObj;
```

### Utilisation en JavaScript
```javascript
// Accès aux exports
const myGameObject = exports.myObject;
const myValue = exports.myNumber;
```

## ️ Console JavaScript

### Fonctions Disponibles
- `console.log()` - Messages normaux
- `console.warn()` - Avertissements
- `console.error()` - Erreurs

### Implémentation
```csharp
var consoleObj = JSObject.NewObject(Context);
consoleObj["log"] = new JSFunction(Context, (args) => {
    Logger.Log(LogType.Log, string.Join(" ", args.Select(e => e.ToString())));
    return JSUndefined.Value;
});
consoleObj["warn"] = new JSFunction(Context, (args) => {
    Logger.Log(LogType.Warning, string.Join(" ", args.Select(e => e.ToString())));
    return JSUndefined.Value;
});
consoleObj["error"] = new JSFunction(Context, (args) => {
    Logger.Log(LogType.Error, string.Join(" ", args.Select(e => e.ToString())));
    return JSUndefined.Value;
});
Context["console"] = consoleObj;
```

##  Objet Behaviour

### Propriétés Exposées
- `behaviour.transform` - Transform du GameObject
- `behaviour.gameObject` - GameObject Unity

### Implémentation
```csharp
var behaviourObj = JSObject.NewObject(Context);
behaviourObj["transform"] = ClrProxy.From(Context, transform);
behaviourObj["gameObject"] = ClrProxy.From(Context, gameObject);
Context["behaviour"] = behaviourObj;
```

### Utilisation en JavaScript
```javascript
import {log} from 'console';

export function onStart() {
    const pos = behaviour.transform.position;
    log(`Position: ${pos.x}, ${pos.y}, ${pos.z}`);

    const name = behaviour.gameObject.name;
    log(`GameObject name: ${name}`);
}
```

##  Invocation de Fonctions

### Méthode Invoke (sans retour)
```csharp
public void Invoke(string methodName, params object[] args) {
    if (Context == null) Prepare();
    if (Context == null || ExecutionContext == null || ExecutionContext.IsNullOrUndefined) return;

    try {
        var method = ExecutionContext[methodName];
        if (method.IsNullOrUndefined) return;

        var jsArgs = args.Select(arg => ClrProxy.From(Context, arg)).ToArray();
        method.InvokeFunction(ExecutionContext, jsArgs);
    } catch (Exception e) {
        NoxLogger.LogError($"Error executing {methodName} function: {e.Message}", this);
    }
}
```

### Méthode Call (avec retour object)
```csharp
public object Call(string functionName, object[] args) {
    // ... validation ...
    var result = method.InvokeFunction(ExecutionContext, jsArgs);
    return result.ConvertTo<object>();
}
```

### Méthode Call<T> (avec retour typé)
```csharp
public T Call<T>(string functionName, object[] args) {
    // ... validation ...
    var result = method.InvokeFunction(ExecutionContext, jsArgs);
    return result.ConvertTo<T>();
}
```

##  Gestion des Propriétés

### GetProperties()
Retourne toutes les propriétés exportées par le script JavaScript.

```csharp
public string[] GetProperties() {
    if (ExecutionContext == null || ExecutionContext.IsNullOrUndefined) return Array.Empty<string>();
    try {
        var keys = new List<string>();
        foreach (var key in ExecutionContext.GetOwnPropertyNames()) {
            keys.Add(key.ToString());
        }
        return keys.ToArray();
    } catch (Exception e) {
        NoxLogger.LogError($"Error getting properties: {e.Message}", this);
        return Array.Empty<string>();
    }
}
```

### GetProperty(string propertyName)
Retourne la valeur d'une propriété spécifique.

```csharp
public object GetProperty(string propertyName) {
    if (ExecutionContext == null || ExecutionContext.IsNullOrUndefined) return null;
    try {
        var prop = ExecutionContext[propertyName];
        return prop.IsNullOrUndefined ? null : prop.ConvertTo<object>();
    } catch (Exception e) {
        NoxLogger.LogError($"Error getting property {propertyName}: {e.Message}", this);
        return null;
    }
}
```

##  Gestion d'Erreurs

### Principe
Toutes les méthodes d'interaction avec JavaScript sont protégées par des blocs try-catch.

### Comportement
- Les erreurs sont loggées via `NoxLogger.LogError()`
- Le contexte est nettoyé en cas d'erreur fatale
- Les fonctions retournent des valeurs par défaut en cas d'erreur

### Exemple
```csharp
try {
    ExecutionContext = Context.Eval(script.asset.text);
    Invoke("onPrepare");
} catch (Exception e) {
    NoxLogger.LogError($"Error executing script: {e.Message}", this);
    NoxLogger.LogException(e, this);
    Context = null;
    ExecutionContext = null;
}
```

##  Callbacks Unity

Le système supporte tous les callbacks Unity standards :
- `onPrepare()` - Appelé après l'initialisation du script
- `onAwake()` - Equivalent Unity Awake
- `onStart()` - Equivalent Unity Start
- `onUpdate()` - Equivalent Unity Update
- `onFixedUpdate()` - Equivalent Unity FixedUpdate
- `onLateUpdate()` - Equivalent Unity LateUpdate
- `onDestroy()` - Equivalent Unity OnDestroy
- `onEnable()` - Equivalent Unity OnEnable
- `onDisable()` - Equivalent Unity OnDisable
- Et beaucoup d'autres...

##  Exemple Complet

### Script JavaScript
```javascript
import {log, warn, error} from 'console';

export let counter = 0;

export function onPrepare() {
    log("Script prepared!");
}

export function onStart() {
    log("Script started!");
    const pos = behaviour.transform.position;
    log(`Starting position: ${pos.x}, ${pos.y}, ${pos.z}`);
}

export function onUpdate() {
    counter++;
    if (counter % 60 === 0) {
        log(`Update called ${counter} times`);
    }
}

export function customFunction(message) {
    log("Custom function called with: " + message);
    return "Response: " + message;
}

export function onDestroy() {
    log("Script destroyed!");
}
```

### Utilisation depuis C#
```csharp
// Appeler une fonction sans retour
yantraScript.InvokeFunction("customFunction", "Hello from C#");

// Appeler une fonction avec retour
string result = yantraScript.CallFunction<string>("customFunction", "Test");
Debug.Log(result); // "Response: Test"

// Lire une propriété
int currentCounter = yantraScript.GetBacking().GetProperty("counter");
```

##  Conversion de Types

### C# → JavaScript
Utilise `ClrProxy.From(Context, value)` :
- Types primitifs (int, float, string, bool)
- Objects Unity (GameObject, Transform, Vector3, etc.)
- Arrays et collections
- Objects C# personnalisés

### JavaScript → C#
Utilise `jsValue.ConvertTo<T>()` :
- Types primitifs
- Strings
- Objects (désérialisés si possible)

## ⚡ Performance

### Optimisations
- Le contexte JavaScript est réutilisé entre les appels
- Les conversions de types sont minimisées
- Les erreurs n'arrêtent pas l'exécution

### Limitations
- Pas de limite de mémoire configurée (contrairement à Jint)
- Pas de limite de récursion configurée
- À configurer selon les besoins du projet

##  Références

- **YantraJS** : https://github.com/yantrajs/yantra
- **YantraJS.Core** : Version 1.2.293
- **Documentation Unity** : Pour les callbacks et types Unity
